(function(){var H=window.NGSHELP;if(!H||!H.S)return;[{"id":"cf-pio","n":"Pass It On (community wishlist)","org":"The Courtney Foundation","cat":["clothes","baby"],"cost":"all","help":"Ask for things you need, like clothes, shoes, baby items, school uniform, bedding and small household items. Local people donate them.","who":"Anyone in Luton who needs an item, or a worker asking for someone they support. Not for cash, food parcels or large furniture.","acc":["online"],"how":"Send a request on The Courtney Foundation website. They check it and get back to you within a week. Your name is never shown. You collect from Raise Up Cafe or the Monday drop-in.","locs":[],"area":"Online request, collect in Luton","web":"https://thecourtneyfoundation.org/"},{"id":"cf-steps","n":"First Steps checklist","org":"The Courtney Foundation","cat":["refugee"],"cost":"all","help":"A free personal checklist for the first weeks after getting refugee status: housing, benefits, bank account, GP, schools, English classes and work.","who":"People with new refugee status in Luton.","acc":["online"],"how":"Open it on The Courtney Foundation website, answer 4 quick questions and it builds your list. Save it with an email and PIN to come back to it.","locs":[],"area":"Online","web":"https://thecourtneyfoundation.org/"}].forEach(function(x){if(!H.S.some(function(y){return y.id===x.id}))H.S.push(x)});})();
